head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > last]<br/>주어진 DOM 요소의 마지막 Element 자식 노드를 반환합니다.",
    "validation" : [
        "element(필수) 파라미터로 마지막 자식을 검색할 DOM 요소를 설정할 수 있어야 합니다.",
        "마지막 Element 타입(nodeType == 1) 자식 노드를 반환해야 합니다.",
        "텍스트 노드 등 Element 가 아닌 노드는 건너뛰어야 합니다.",
        "element 파라미터에 자식 노드가 없으면 null 을 반환해야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof grp_test !== 'undefined') {
        grp_test.remove();
    }
    if (typeof grp_empty !== 'undefined') {
        grp_empty.remove();
    }

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // grp_test: 자식 3개를 가진 그룹
    let strGrpTest = '<xf:group ' + ns + ' style=""></xf:group>';
    scwin.grp_test = await $p.dynamicCreate('grp_test', 'group', strGrpTest, grp_comp);

    let strChild1 = '<w2:textbox ' + ns + ' label="첫번째" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child1', 'textbox', strChild1, scwin.grp_test);

    let strChild2 = '<w2:textbox ' + ns + ' label="두번째" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child2', 'textbox', strChild2, scwin.grp_test);

    let strChild3 = '<w2:textbox ' + ns + ' label="세번째" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child3', 'textbox', strChild3, scwin.grp_test);

    // 마지막 자식 뒤에 텍스트 노드 삽입 (Element 가 아닌 노드 건너뛰기 검증용)
    let grpTestEl = document.querySelector("div[id*='grp_test']");
    let textNode = document.createTextNode("텍스트 노드");
    grpTestEl.appendChild(textNode);

    // grp_empty: 자식 없는 그룹
    let strGrpEmpty = '<xf:group ' + ns + ' style=""></xf:group>';
    scwin.grp_empty = await $p.dynamicCreate('grp_empty', 'group', strGrpEmpty, grp_comp);
}



scwin.onpageload = async function () {
    $c.gcm.createCommonDatalist();
    await scwin.comp_init();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_last_onclick = function () {
    let elementType = par_element.getValue();

    let element;
    if (elementType === 'grp_test') {
        element = document.querySelector("div[id*='grp_test']");
    } else if (elementType === 'grp_empty') {
        element = document.querySelector("div[id*='grp_empty']");
    }

    let ret = WebSquare.util.last(element);

    let result = [];
    if (ret) {
        result.push("tagName: " + ret.tagName);
        result.push("nodeType: " + ret.nodeType);
        result.push("id: " + (ret.id || '(없음)'));
    } else {
        result.push("반환값: null");
    }

    // DOM lastChild 와 비교하여 텍스트 노드 건너뛰기 검증
    let domLastChild = element ? element.lastChild : null;
    if (domLastChild) {
        result.push("DOM lastChild nodeType: " + domLastChild.nodeType);
    }

    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
